            summer=("Une salade, une pastèque, un verre frais : voilà le menu de l'été. Et du fromage, toujours du fromage.", "A salad, a melon, a cool drink: summer's menu. And cheese, always cheese."),
            autumn=("L'automne, saison du potiron ! Je pourrais en faire un menu entier. Et je le fais.", "Autumn, pumpkin season! I could make a whole menu of it. And I do."),
