def tables() -> Dict[str, Any]:
    npcs: Dict[str, Any] = {}
    dialogues: Dict[str, Any] = {}
    events: Dict[str, Any] = {}
    for n in NPCS:
        nid = n["id"].upper()
        talk_keys: Dict[str, Any] = {}
        for k, v in n["talk"].items():
            if isinstance(v, list):
                talk_keys[k] = ["D_%s_%s_%d" % (nid, k.upper(), i + 1) for i in range(len(v))]
            else:
                talk_keys[k] = ["D_%s_%s_1" % (nid, k.upper())]
        npcs[n["id"]] = {
            "birthday": [SEASONS.index(n["bday"][0]), n["bday"][1]], "romance": n["romance"], "home": n["home"],
            "loves": n["loves"], "likes": n["likes"], "dislikes": n["dislikes"], "hates": n["hates"],
            "schedule": n["sched"], "talk": talk_keys, "events": [e["id"] for e in n["events"]],
            "sprite": n["id"],
        }
        for e in n["events"]:
            eid = e["id"].upper()
            events[e["id"]] = {
                "npc": n["id"], "hearts": e["hearts"],
                "lines": ["EV_%s_L%d" % (eid, i + 1) for i in range(len(e["lines"]))],
                "options": [{"label": "EV_%s_O%d" % (eid, i + 1), "reply": "EV_%s_R%d" % (eid, i + 1), "points": opt[2]}
                            for i, opt in enumerate(e["options"])],
                "reward": {"item": e["reward"][0], "n": e["reward"][1]},
            }
        dialogues[n["id"]] = {}
    return {"npcs": npcs, "dialogues": dialogues, "events": events}


def strings() -> Dict[str, Tuple[str, str]]:
    out: Dict[str, Tuple[str, str]] = {}
    for n in NPCS:
        nid = n["id"].upper()
        out["NPC_" + nid] = (n["fr"], n["en"])
        out["JOB_" + nid] = n["job"]
        out["BIO_" + nid] = n["bio"]
        for k, v in n["talk"].items():
            if isinstance(v, list):
                for i, pair in enumerate(v):
                    out["D_%s_%s_%d" % (nid, k.upper(), i + 1)] = pair
            else:
                out["D_%s_%s_1" % (nid, k.upper())] = v
        for e in n["events"]:
            eid = e["id"].upper()
            for i, pair in enumerate(e["lines"]):
                out["EV_%s_L%d" % (eid, i + 1)] = pair
            for i, (label, reply, _pts) in enumerate(e["options"]):
                out["EV_%s_O%d" % (eid, i + 1)] = label
                out["EV_%s_R%d" % (eid, i + 1)] = reply
    return out
